{"file_path":"src/parse.js","content":"export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

const newTable = () => ({ kind: 'table', map: new Map(), header: false })
const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const isComment = (c) => c === '#' || c === ';'

export function parse(input) {
  const lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let current = root
  lines.forEach((text, i) => {
    const fail = (m) => {
      throw new ParseError(m, i + 1)
    }
    current = parseLine(text, root, current, fail)
  })
  return root
}

function parseLine(s, root, current, fail) {
  let p = 0
  const skip = () => {
    while (p < s.length && isWs(s[p])) p++
  }
  skip()
  if (p >= s.length || isComment(s[p])) return current

  function str() {
    const q = s[p++]
    let out = ''
    if (q === "'") {
      const e = s.indexOf("'", p)
      if (e < 0) fail('unterminated string')
      out = s.slice(p, e)
      p = e + 1
      return out
    }
    for (;;) {
      if (p >= s.length) fail('unterminated string')
      const c = s[p++]
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      if (p >= s.length) fail('unterminated string')
      const e = String.fromCodePoint(s.codePointAt(p))
      p += e.length
      const simple = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(simple, e)) out += simple[e]
      else if (e === 'u') {
        const h = s.slice(p, p + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        p += 4
      } else fail('invalid escape \\' + e)
    }
  }

  function name() {
    if (s[p] === '"' || s[p] === "'") return str()
    const st = p
    while (p < s.length && BARE.test(s[p])) p++
    if (p === st) fail('expected a name')
    return s.slice(st, p)
  }

  function dotted() {
    skip()
    const parts = [name()]
    for (;;) {
      const save = p
      skip()
      if (s[p] === '.') {
        p++
        skip()
        parts.push(name())
      } else {
        p = save
        return parts
      }
    }
  }

  function atEnd() {
    skip()
    return p >= s.length || isComment(s[p])
  }

  function value(prefix) {
    skip()
    if (p >= s.length || isComment(s[p]) || s[p] === ',' || s[p] === ']' || s[p] === '}') fail('expected a value')
    const c = s[p]
    if (c === '"' || c === "'") return { kind: 'string', value: str() }
    if (c === '[') {
      p++
      const items = []
      for (;;) {
        if (atEnd()) fail('unterminated array')
        if (s[p] === ']') {
          p++
          return { kind: 'array', items, aot: false }
        }
        items.push(value(prefix))
        if (atEnd()) fail('unterminated array')
        if (s[p] === ',') p++
        else if (s[p] !== ']') fail('unterminated array')
      }
    }
    if (c === '{') {
      p++
      const t = newTable()
      if (atEnd()) fail('unterminated inline table')
      if (s[p] === '}') {
        p++
        return t
      }
      for (;;) {
        if (atEnd()) fail('unterminated inline table')
        const parts = dotted()
        skip()
        if (s[p] !== '=') fail('expected = in an inline table')
        p++
        assign(t, parts, prefix, () => value(prefix))
        if (atEnd()) fail('unterminated inline table')
        if (s[p] === ',') p++
        else if (s[p] === '}') {
          p++
          return t
        } else fail('unterminated inline table')
      }
    }
    const st = p
    while (p < s.length && !isWs(s[p]) && s[p] !== ',' && s[p] !== ']' && s[p] !== '}') p++
    const w = s.slice(st, p)
    if (w === 'true') return { kind: 'boolean', value: true }
    if (w === 'false') return { kind: 'boolean', value: false }
    const I = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp(`^${I}$`).test(w)) return { kind: 'integer', value: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^${I}(?:\\.\\d+(?:_\\d+)*)?(?:[eE][+-]?\\d+(?:_\\d+)*)?$`).test(w))
      return { kind: 'float', value: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  const pathStr = (base, parts, n) => base.concat(parts.slice(0, n)).join('.')

  // Walk the dotted prefix from `from`, creating tables; returns the table holding the last part.
  function walk(from, base, parts, createFail) {
    let t = from
    for (let k = 0; k < parts.length - 1; k++) {
      let n = t.map.get(parts[k])
      if (n === undefined) {
        n = newTable()
        t.map.set(parts[k], n)
      } else if (n.kind === 'array' && n.aot) n = n.items[n.items.length - 1]
      else if (n.kind !== 'table') fail(`${pathStr(base, parts, k + 1)} is not a table`)
      t = n
    }
    return t
  }

  function assign(table, parts, base, getValue) {
    const t = walk(table, base, parts)
    const last = parts[parts.length - 1]
    if (t.map.has(last)) fail(`key ${pathStr(base, parts, parts.length)} is defined twice`)
    t.map.set(last, getValue())
  }

  if (s[p] === '[') {
    const dbl = s[p + 1] === '['
    p += dbl ? 2 : 1
    const parts = dotted()
    skip()
    if (p >= s.length || isComment(s[p])) fail('unterminated table header')
    if (s[p] !== ']') fail('unterminated table header')
    p++
    if (dbl) {
      if (s[p] !== ']') fail('unterminated table header')
      p++
    }
    if (!atEnd()) fail('trailing text after a table header')
    const t = walk(root, [], parts)
    const last = parts[parts.length - 1]
    const full = parts.join('.')
    const ex = t.map.get(last)
    if (dbl) {
      const fresh = newTable()
      fresh.header = true
      if (ex === undefined) t.map.set(last, { kind: 'array', items: [fresh], aot: true })
      else if (ex.kind === 'array' && ex.aot) ex.items.push(fresh)
      else fail(`${full} is not an array of tables`)
      return fresh
    }
    if (ex === undefined) {
      const n = newTable()
      n.header = true
      t.map.set(last, n)
      return n
    }
    if (ex.kind !== 'table') fail(`${full} is not a table`)
    if (ex.header) fail(`table ${full} is defined twice`)
    ex.header = true
    return ex
  }

  // key = value: path in messages counts from the root, so the current table's path is needed.
  const parts = dotted()
  skip()
  if (s[p] !== '=') fail('expected key = value')
  p++
  const base = current.path || []
  assign(current, parts, base, () => {
    const v = value(base.concat(parts))
    if (!atEnd()) fail('trailing text after a value')
    return v
  })
  return current
}
"}

